-- Mapping groups and types used by the Bahmni module
INSERT INTO mapping_group (name, integration_system_id, uuid, is_voided)
SELECT v.name, (SELECT id FROM integration_system WHERE name = 'bahmni'), uuid_generate_v4(), false
FROM (VALUES
    ('GeneralEncounter'),
    ('Observation'),
    ('Common')
) AS v(name)
WHERE NOT EXISTS (SELECT 1 FROM mapping_group t WHERE t.name = v.name AND t.integration_system_id = (SELECT id FROM integration_system WHERE name = 'bahmni'));

INSERT INTO mapping_type (name, integration_system_id, uuid, is_voided)
SELECT v.name, (SELECT id FROM integration_system WHERE name = 'bahmni'), uuid_generate_v4(), false
FROM (VALUES
    ('EncounterType'),
    ('Concept'),
    ('BahmniUUID_Concept'),
    ('LabEncounterType'),
    ('DrugOrderEncounterType'),
    ('DrugOrderConcept')
) AS v(name)
WHERE NOT EXISTS (SELECT 1 FROM mapping_type t WHERE t.name = v.name AND t.integration_system_id = (SELECT id FROM integration_system WHERE name = 'bahmni'));

