CROSS JOIN (
    SELECT s.id AS system_id,
           (SELECT g.id FROM mapping_group g WHERE g.name = 'Observation' AND g.integration_system_id = s.id LIMIT 1) AS group_id,
           (SELECT t.id FROM mapping_type t WHERE t.name = 'Concept' AND t.integration_system_id = s.id LIMIT 1) AS type_id
    FROM integration_system s WHERE s.name = 'bahmni'
) AS b
WHERE NOT EXISTS (
    SELECT 1 FROM mapping_metadata m
    WHERE m.int_system_value = v.int_system_value AND m.mapping_type_id = b.type_id AND m.is_voided = false
);

